mapper.select:
select * from pm_data_share_msg

    and unit_name = #{unitName}
    and tx_date = #{txDate}

mapper.delete:
delete from pm_data_share_msg

    and file_name = #{fileName}
    and unit_name = #{unitName}

mapper.update:
update pm_data_share_msg
log_msg = #{logMsg}, down_flag = #{downFlag}, process_flag = #{processFlag}, is_done = #{isDone},
where file_name = #{fileName} and file_dir = #{fileDir}

update pm_data_share_msg

    log_msg = #{logMsg},
    down_flag = #{downFlag},
    file_desc = #{fileDesc},
    file_num = #{fileNum},

where file_name = #{fileName}
and unit_name = #{unitName}
and tx_date = #{txDate}
and file_type = #{fileType}
